CREATE TABLE ty_pr_metric(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),code text NOT NULL,name text NOT NULL,
 version integer NOT NULL CHECK(version>0),revision integer NOT NULL DEFAULT 1,kind text NOT NULL CHECK(kind IN('quantitative','behavior','deduction','informational')),
 unit text NOT NULL,direction text NOT NULL DEFAULT'up'CHECK(direction IN('up','down','none')),score_min numeric(18,6)NOT NULL DEFAULT 0,score_max numeric(18,6)NOT NULL DEFAULT 100,
 rules jsonb NOT NULL DEFAULT'{}',status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','published','inactive')),
 created_by bigint NOT NULL REFERENCES sys_account(id),published_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,
 UNIQUE(group_id,code,version),CHECK(score_max>score_min),CHECK(jsonb_typeof(rules)='object')
);
CREATE TABLE ty_pr_template(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),code text NOT NULL,name text NOT NULL,
 version integer NOT NULL CHECK(version>0),revision integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','published','inactive')),
 mode text NOT NULL DEFAULT'simple'CHECK(mode IN('simple','standard','operating_bonus')),config jsonb NOT NULL,
 created_by bigint NOT NULL REFERENCES sys_account(id),published_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,
 UNIQUE(group_id,code,version),CHECK(jsonb_typeof(config)='object')
);
CREATE TABLE ty_pr_cycle_root(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),canonical_business_key text NOT NULL,label text NOT NULL,
 starts_on date NOT NULL,ends_on date NOT NULL,payout_period date,created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(group_id,canonical_business_key),CHECK(ends_on>starts_on),CHECK(payout_period IS NULL OR extract(day FROM payout_period)=1)
);
CREATE TABLE ty_pr_plan(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cycle_root_id bigint NOT NULL REFERENCES ty_pr_cycle_root(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 template_id bigint NOT NULL REFERENCES ty_pr_template(id),version integer NOT NULL CHECK(version>0),revision integer NOT NULL DEFAULT 1,label text NOT NULL,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','running','paused','completed','cancelled')),config_snapshot jsonb NOT NULL,
 source_plan_id bigint REFERENCES ty_pr_plan(id),launched_by bigint REFERENCES sys_account(id),launched_at timestamptz,
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(cycle_root_id,version)
);
CREATE TABLE ty_pr_plan_company(plan_id bigint NOT NULL REFERENCES ty_pr_plan(id),company_id bigint NOT NULL REFERENCES ty_company(id),PRIMARY KEY(plan_id,company_id));
CREATE TABLE ty_pr_target(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,plan_id bigint NOT NULL REFERENCES ty_pr_plan(id),group_id bigint NOT NULL,company_id bigint NOT NULL,
 person_id bigint NOT NULL,employment_id bigint NOT NULL,evaluation_context text NOT NULL DEFAULT'primary',revision integer NOT NULL DEFAULT 1,
 status text NOT NULL DEFAULT'active'CHECK(status IN('active','excluded')),exclusion_reason text,personnel_snapshot jsonb NOT NULL,
 goal_state text NOT NULL DEFAULT'draft'CHECK(goal_state IN('draft','confirmed')),goals jsonb NOT NULL DEFAULT'[]',progress jsonb NOT NULL DEFAULT'[]',
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),
 FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),UNIQUE(plan_id,employment_id,evaluation_context)
);
CREATE TABLE ty_pr_org_input(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,plan_id bigint NOT NULL REFERENCES ty_pr_plan(id),group_id bigint NOT NULL,company_id bigint NOT NULL,
 period date NOT NULL,metric_code text NOT NULL,revision integer NOT NULL DEFAULT 1,values jsonb NOT NULL,state text NOT NULL DEFAULT'draft'CHECK(state IN('draft','verified')),
 created_by bigint NOT NULL REFERENCES sys_account(id),verified_by bigint REFERENCES sys_account(id),evidence_ref text NOT NULL,source_hash text,
 created_at timestamptz NOT NULL DEFAULT now(),verified_at timestamptz,FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),
 UNIQUE(plan_id,company_id,period,metric_code),CHECK(extract(day FROM period)=1)
);
CREATE TABLE ty_pr_rating_assignment(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,target_id bigint NOT NULL REFERENCES ty_pr_target(id),role_code text NOT NULL CHECK(role_code IN('self','supervisor','peer','subordinate','designated')),
 rater_account_id bigint NOT NULL REFERENCES sys_account(id),rater_identity_key text NOT NULL,reviewer_account_id bigint REFERENCES sys_account(id),
 revision integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT'assigned'CHECK(status IN('assigned','draft','submitted','reviewed','returned','cancelled')),
 current_rating_id bigint,due_at timestamptz,created_by bigint NOT NULL REFERENCES sys_account(id),reason text,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(target_id,role_code,rater_identity_key)
);
CREATE TABLE ty_pr_rating_revision(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,assignment_id bigint NOT NULL REFERENCES ty_pr_rating_assignment(id),version integer NOT NULL CHECK(version>0),
 status text NOT NULL CHECK(status IN('draft','submitted','reviewed','returned')),values jsonb NOT NULL,comment text,source_hash text,
 actor_id bigint NOT NULL REFERENCES sys_account(id),submitted_at timestamptz,reviewed_by bigint REFERENCES sys_account(id),reviewed_at timestamptz,review_reason text,
 created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(assignment_id,version)
);
ALTER TABLE ty_pr_rating_assignment ADD CONSTRAINT ty_pr_current_rating FOREIGN KEY(current_rating_id)REFERENCES ty_pr_rating_revision(id);
CREATE TABLE ty_pr_result_root(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cycle_root_id bigint NOT NULL REFERENCES ty_pr_cycle_root(id),group_id bigint NOT NULL,company_id bigint NOT NULL,
 person_id bigint NOT NULL,employment_id bigint NOT NULL,evaluation_context text NOT NULL,
 current_approved_id bigint,current_published_id bigint,head_revision integer NOT NULL DEFAULT 0,
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),
 FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),UNIQUE(cycle_root_id,employment_id,evaluation_context)
);
CREATE TABLE ty_pr_result_version(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,root_id bigint NOT NULL REFERENCES ty_pr_result_root(id),target_id bigint NOT NULL REFERENCES ty_pr_target(id),
 version integer NOT NULL CHECK(version>0),revision integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT'calculated'CHECK(status IN('calculated','proposed','approved','rejected','cancelled')),
 expected_head_revision integer NOT NULL,expected_approved_id bigint REFERENCES ty_pr_result_version(id),
 score numeric(18,6),grade text,original_score numeric(18,6),calibration_reason text,source_snapshot jsonb NOT NULL,source_hash text NOT NULL,issues jsonb NOT NULL DEFAULT'[]',
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),approval_reason text,approval_instance_id bigint REFERENCES ty_workflow_instance(id),
 created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,UNIQUE(root_id,version),CHECK(length(source_hash)=64),CHECK(jsonb_typeof(issues)='array')
);
ALTER TABLE ty_pr_result_root ADD CONSTRAINT ty_pr_result_head FOREIGN KEY(current_approved_id)REFERENCES ty_pr_result_version(id);
CREATE TABLE ty_pr_publication(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,result_id bigint NOT NULL REFERENCES ty_pr_result_version(id),root_id bigint NOT NULL REFERENCES ty_pr_result_root(id),
 version integer NOT NULL CHECK(version>0),state text NOT NULL DEFAULT'published'CHECK(state IN('published','withdrawn')),published_by bigint NOT NULL REFERENCES sys_account(id),
 published_at timestamptz NOT NULL DEFAULT now(),withdrawn_by bigint REFERENCES sys_account(id),withdrawn_at timestamptz,withdraw_reason text,UNIQUE(root_id,version),UNIQUE(result_id)
);
ALTER TABLE ty_pr_result_root ADD CONSTRAINT ty_pr_publication_head FOREIGN KEY(current_published_id)REFERENCES ty_pr_publication(id);
CREATE TABLE ty_pr_acknowledgment(
 publication_id bigint NOT NULL REFERENCES ty_pr_publication(id),person_id bigint NOT NULL REFERENCES ty_person(id),actor_id bigint NOT NULL REFERENCES sys_account(id),acknowledged_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(publication_id,person_id)
);
CREATE TABLE ty_pr_appeal(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,publication_id bigint NOT NULL REFERENCES ty_pr_publication(id),person_id bigint NOT NULL REFERENCES ty_person(id),
 revision integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT'pending'CHECK(status IN('pending','upheld','corrected','rejected','withdrawn')),reason text NOT NULL,evidence_ref text,
 block_bonus boolean NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),decided_by bigint REFERENCES sys_account(id),decision_reason text,
 corrected_result_id bigint REFERENCES ty_pr_result_version(id),created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz
);
CREATE UNIQUE INDEX ty_pr_open_appeal ON ty_pr_appeal(publication_id,person_id)WHERE status='pending';
CREATE TABLE ty_pr_bonus_month(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,target_id bigint NOT NULL REFERENCES ty_pr_target(id),period date NOT NULL,revision integer NOT NULL DEFAULT 1,
 attainment numeric(24,10),bonus_base numeric(24,8),base_unit text NOT NULL CHECK(base_unit IN('monthly','quarterly','annual')),eligibility_weight numeric(20,10),
 grade_id bigint REFERENCES ty_grade(id),currency text NOT NULL CHECK(currency IN('CNY','HKD')),state text NOT NULL DEFAULT'draft'CHECK(state IN('draft','verified')),
 created_by bigint NOT NULL REFERENCES sys_account(id),verified_by bigint REFERENCES sys_account(id),evidence_ref text NOT NULL,source_ref jsonb NOT NULL DEFAULT'{}',
 UNIQUE(target_id,period),CHECK(extract(day FROM period)=1),CHECK(bonus_base>=0),CHECK(eligibility_weight>=0 AND eligibility_weight<=1)
);
CREATE TABLE ty_pr_award_parent(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cycle_root_id bigint NOT NULL REFERENCES ty_pr_cycle_root(id),group_id bigint NOT NULL,company_id bigint NOT NULL,
 person_id bigint NOT NULL,employment_id bigint NOT NULL,purpose_code text NOT NULL,item_code text NOT NULL REFERENCES ty_pay_item_catalog(code),
 currency text NOT NULL CHECK(currency IN('CNY','HKD')),current_approved_id bigint,head_revision integer NOT NULL DEFAULT 0,
 FOREIGN KEY(company_id,group_id)REFERENCES ty_company(id,group_id),FOREIGN KEY(person_id,group_id)REFERENCES ty_person(id,group_id),
 FOREIGN KEY(employment_id,company_id,group_id)REFERENCES ty_employment(id,company_id,group_id),UNIQUE(cycle_root_id,employment_id,purpose_code)
);
CREATE TABLE ty_pr_bonus_trial(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,parent_id bigint NOT NULL REFERENCES ty_pr_award_parent(id),result_id bigint NOT NULL REFERENCES ty_pr_result_version(id),
 source_hash text NOT NULL,source_snapshot jsonb NOT NULL,algorithm_a_amount numeric(24,2),algorithm_b_amount numeric(24,2),details jsonb NOT NULL,issues jsonb NOT NULL,
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(length(source_hash)=64)
);
CREATE TABLE ty_pr_award_revision(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,parent_id bigint NOT NULL REFERENCES ty_pr_award_parent(id),version integer NOT NULL CHECK(version>0),revision integer NOT NULL DEFAULT 1,
 trial_id bigint NOT NULL REFERENCES ty_pr_bonus_trial(id),result_id bigint NOT NULL REFERENCES ty_pr_result_version(id),algorithm text NOT NULL CHECK(algorithm IN('A','B')),
 target_amount numeric(24,2)NOT NULL CHECK(target_amount>=0),payout_period date NOT NULL CHECK(extract(day FROM payout_period)=1),
 status text NOT NULL DEFAULT'proposed'CHECK(status IN('proposed','approved','rejected','cancelled')),expected_head_revision integer NOT NULL,
 source_hash text NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),reason text NOT NULL,
 recovery_basis_ref text,created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,UNIQUE(parent_id,version),CHECK(length(source_hash)=64)
);
ALTER TABLE ty_pr_award_parent ADD CONSTRAINT ty_pr_award_head FOREIGN KEY(current_approved_id)REFERENCES ty_pr_award_revision(id);
CREATE TABLE ty_pr_source_alias(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,parent_id bigint NOT NULL REFERENCES ty_pr_award_parent(id),source_domain text NOT NULL CHECK(source_domain='performance_result'),
 legacy_cycle_id bigint NOT NULL REFERENCES ty_perf_cycle(id),legacy_employment_id bigint NOT NULL REFERENCES ty_employment(id),canonical_economic_key text NOT NULL,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint NOT NULL REFERENCES sys_account(id),reason text NOT NULL,evidence_ref text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(legacy_cycle_id,legacy_employment_id),CHECK(created_by<>approved_by)
);
CREATE TABLE ty_pr_notice(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),recipient_account_id bigint NOT NULL REFERENCES sys_account(id),
 event_key text NOT NULL,kind text NOT NULL,subject_type text NOT NULL,subject_id bigint NOT NULL,title text NOT NULL,
 channel text NOT NULL DEFAULT'internal'CHECK(channel='internal'),delivery_state text NOT NULL DEFAULT'recorded'CHECK(delivery_state='recorded'),read_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,recipient_account_id,event_key)
);
CREATE TABLE ty_pr_import_batch(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),plan_id bigint REFERENCES ty_pr_plan(id),
 kind text NOT NULL CHECK(kind IN('org_input','bonus_month','historical_score')),namespace text NOT NULL,filename text NOT NULL,source_hash text NOT NULL,
 parsed_rows jsonb NOT NULL,issues jsonb NOT NULL,status text NOT NULL CHECK(status IN('validated','invalid','applied')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,namespace,kind,source_hash)
);
CREATE TABLE ty_pr_event(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),entity_type text NOT NULL,entity_id bigint NOT NULL,
 action text NOT NULL,actor_id bigint NOT NULL REFERENCES sys_account(id),before_data jsonb,after_data jsonb NOT NULL,reason text,created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE ty_pr_source_alias ADD COLUMN proposal_event_id bigint NOT NULL REFERENCES ty_pr_event(id);
CREATE FUNCTION fn_ty_pr_keep()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='绩效来源、版本和办理历史不得直接删除或改写';END;$$;
CREATE FUNCTION fn_ty_pr_actor_is_person(actor bigint,gid bigint,pid bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT EXISTS(SELECT 1 FROM public.sys_account a LEFT JOIN public.ty_operator_binding b ON b.account_id=a.id LEFT JOIN public.ty_test_account_profile p ON p.account_id=a.id LEFT JOIN public.ty_person t ON t.id=pid AND t.group_id=gid WHERE a.id=actor AND
 (CASE WHEN b.account_id IS NOT NULL THEN b.group_id=gid AND b.person_id=pid ELSE p.group_id=gid AND p.person_id=pid END OR a.person_id IS NOT NULL AND a.person_id=t.legacy_person_id));$$;
CREATE FUNCTION fn_ty_pr_bound_person(actor bigint,gid bigint,pid bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT EXISTS(SELECT 1 FROM public.sys_account a LEFT JOIN public.ty_operator_binding b ON b.account_id=a.id LEFT JOIN public.ty_test_account_profile p ON p.account_id=a.id WHERE a.id=actor AND a.status='active'AND CASE WHEN b.account_id IS NOT NULL THEN b.group_id=gid AND b.person_id=pid AND b.status='active'ELSE p.group_id=gid AND p.person_id=pid END);$$;
CREATE FUNCTION fn_ty_pr_same_actor(a bigint,b bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT a=b OR EXISTS(SELECT 1 FROM public.ty_person p WHERE public.fn_ty_pr_actor_is_person(a,p.group_id,p.id)AND public.fn_ty_pr_actor_is_person(b,p.group_id,p.id));$$;
CREATE FUNCTION fn_ty_pr_template_problem(config jsonb)RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=''AS $$
DECLARE item jsonb;role jsonb;total numeric:=0;roles_total numeric:=0;seen text[]:='{}';role_seen text[]:='{}';org_weight numeric;band jsonb;thresholds numeric[]:='{}';bonus_policy jsonb;org_rules jsonb;org_metric jsonb;bands_seen numeric[];org_codes text[]:='{}';
BEGIN
 IF jsonb_typeof(config->'items')IS DISTINCT FROM'array'OR jsonb_typeof(config->'roles')IS DISTINCT FROM'array'THEN RETURN'模板须明确指标与评分角色';END IF;
 IF jsonb_array_length(config->'items')<1 OR jsonb_array_length(config->'items')>100 THEN RETURN'模板须有1至100个指标';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(config->'items')LOOP
  IF coalesce(btrim(item->>'code'),'')=''OR item->>'code'=ANY(seen)THEN RETURN'模板指标编码缺失或重复';END IF;seen:=array_append(seen,item->>'code');
  IF coalesce(item->>'unit','')=''OR NOT(item?'weight')OR(item->>'weight')::numeric<0 OR(item->>'weight')::numeric>1 THEN RETURN'指标单位与明确比例权重无效';END IF;
  IF coalesce((item->>'score_max')::numeric,100)<=coalesce((item->>'score_min')::numeric,0)THEN RETURN'指标评分上下限无效';END IF;
  IF coalesce(item->>'scoring_mode','direct')NOT IN('direct','normalize_to_100')THEN RETURN'指标折分模式须明确';END IF;
  total:=total+(item->>'weight')::numeric;
 END LOOP;
 IF total<>1 THEN RETURN'指标权重须精确合计1，缺项不自动重分权重';END IF;
 org_weight:=coalesce((config->>'organization_weight')::numeric,0);IF org_weight<0 OR org_weight>1 THEN RETURN'组织成绩权重须在0至1';END IF;
 FOR role IN SELECT value FROM jsonb_array_elements(config->'roles')LOOP
  IF coalesce(role->>'code','')NOT IN('self','supervisor','peer','subordinate','designated')OR role->>'code'=ANY(role_seen)THEN RETURN'评分角色无效或重复';END IF;role_seen:=array_append(role_seen,role->>'code');
  IF NOT(role?'weight')OR(role->>'weight')::numeric<0 OR(role->>'weight')::numeric>1 OR coalesce((role->>'minimum_count')::integer,0)<1 THEN RETURN'角色权重及最少真实评分人数无效';END IF;
  IF coalesce((config->>'anonymous_peer')::boolean,false)AND role->>'code'IN('peer','subordinate')AND(role->>'minimum_count')::integer<greatest(coalesce((config->>'anonymous_minimum')::integer,3),3)THEN RETURN'匿名角色最少真实人数不得低于3';END IF;
  roles_total:=roles_total+(role->>'weight')::numeric;
 END LOOP;
 IF org_weight<1 AND roles_total<>1 THEN RETURN'个人评分角色权重须精确合计1';END IF;
 IF org_weight=1 AND roles_total<>0 AND roles_total<>1 THEN RETURN'经营指标模式不能混入未明确比例的个人评分';END IF;
 IF jsonb_typeof(config->'rating_bands')IS DISTINCT FROM'array'OR jsonb_array_length(config->'rating_bands')<1 THEN RETURN'须明确等级阈值';END IF;
 FOR band IN SELECT value FROM jsonb_array_elements(config->'rating_bands')LOOP
  IF coalesce(btrim(band->>'grade'),'')=''OR band->>'min_score'IS NULL OR band->>'factor'IS NULL OR(band->>'factor')::numeric<0 OR(band->>'min_score')::numeric=ANY(thresholds)THEN RETURN'等级边界重复或缺少明确系数';END IF;thresholds:=array_append(thresholds,(band->>'min_score')::numeric);
 END LOOP;
 IF org_weight>0 THEN
  org_rules:=config->'organization_rules';IF coalesce((org_rules->>'confirmed')::boolean,false)IS NOT TRUE OR coalesce((org_rules->>'score_base')::numeric,0)<=0 OR coalesce((org_rules->>'score_floor')::numeric,0)<0 OR jsonb_typeof(org_rules->'metrics')IS DISTINCT FROM'array'OR jsonb_array_length(org_rules->'metrics')=0 THEN RETURN'组织评分须明确核定的起评分、下限和指标规则';END IF;
  FOR org_metric IN SELECT value FROM jsonb_array_elements(org_rules->'metrics')LOOP
   IF coalesce(btrim(org_metric->>'code'),'')=''OR org_metric->>'code'=ANY(org_codes)OR coalesce(btrim(org_metric->>'unit'),'')=''OR org_metric->>'method'NOT IN('direct_deduction','deduction_bands','target_attainment')OR coalesce((org_metric->>'weight')::numeric,1)<0 THEN RETURN'组织指标编码/单位/方法/权重无效';END IF;org_codes:=array_append(org_codes,org_metric->>'code');
   IF org_metric->>'method'<>'direct_deduction'THEN
    IF jsonb_typeof(org_metric->'bands')IS DISTINCT FROM'array'OR jsonb_array_length(org_metric->'bands')=0 THEN RETURN'分段扣分/目标达成须配置边界';END IF;
    FOR band IN SELECT value FROM jsonb_array_elements(org_metric->'bands')LOOP IF band->>'deduction'IS NULL OR(band->>'deduction')::numeric<0 OR band?'min'AND band?'max'AND(band->>'min')::numeric>=(band->>'max')::numeric THEN RETURN'组织指标扣分或分段区间无效';END IF;END LOOP;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(org_metric->'bands')WITH ORDINALITY x(b,i)CROSS JOIN jsonb_array_elements(org_metric->'bands')WITH ORDINALITY y(b,j)WHERE x.i<y.j AND numrange((x.b->>'min')::numeric,(x.b->>'max')::numeric,'[)')&&numrange((y.b->>'min')::numeric,(y.b->>'max')::numeric,'[)'))THEN RETURN'组织指标扣分区间不可重叠';END IF;
   END IF;
  END LOOP;
 END IF;
 bonus_policy:=config->'bonus_policy';IF coalesce((bonus_policy->>'confirmed')::boolean,false)THEN
  IF bonus_policy->>'algorithm_a_aggregation'NOT IN('mean','sum')OR bonus_policy->>'algorithm_a_rounding'NOT IN('floor','half_up_2')OR bonus_policy->>'algorithm_b_rounding'NOT IN('floor','half_up_2')OR jsonb_typeof(bonus_policy->'rating_bands')IS DISTINCT FROM'array'OR jsonb_array_length(bonus_policy->'rating_bands')=0 THEN RETURN'已启用奖金须明确两套算法次序、舍入与等级';END IF;
  bands_seen:='{}';FOR band IN SELECT value FROM jsonb_array_elements(bonus_policy->'rating_bands')LOOP IF band->>'min_score'IS NULL OR band->>'factor'IS NULL OR(band->>'factor')::numeric<0 OR(band->>'min_score')::numeric=ANY(bands_seen)OR coalesce(btrim(band->>'grade'),'')=''THEN RETURN'奖金等级阈值重复或缺少明确系数';END IF;bands_seen:=array_append(bands_seen,(band->>'min_score')::numeric);END LOOP;
 END IF;
 RETURN NULL;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR division_by_zero THEN RETURN'模板含非法数值或单位';END;$$;
CREATE FUNCTION fn_ty_pr_definition_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE problem text;
BEGIN
 IF TG_OP='UPDATE'THEN
  IF NEW.group_id<>OLD.group_id OR NEW.code<>OLD.code OR NEW.version<>OLD.version OR NEW.created_by<>OLD.created_by OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='配置身份与版本不可改换且修订须连续';END IF;
  IF OLD.status<>'draft'AND(to_jsonb(NEW)-ARRAY['status','revision'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已用绩效配置不可原地重写';END IF;
  IF OLD.status<>'draft'AND NEW.status<>'inactive'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已发布配置只能停用或复制新版';END IF;
 END IF;
 IF NEW.status='published'THEN
  IF NEW.published_by IS NULL OR NEW.published_at IS NULL OR public.fn_ty_pr_same_actor(NEW.created_by,NEW.published_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='配置发布须独立复核并留真实人员';END IF;
  IF TG_TABLE_NAME='ty_pr_template'THEN problem:=public.fn_ty_pr_template_problem(NEW.config);IF problem IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE=problem;END IF;END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_metric_guard BEFORE INSERT OR UPDATE ON ty_pr_metric FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_definition_guard();
CREATE TRIGGER ty_pr_template_guard BEFORE INSERT OR UPDATE ON ty_pr_template FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_definition_guard();
CREATE FUNCTION fn_ty_pr_plan_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE c public.ty_pr_cycle_root%ROWTYPE;t public.ty_pr_template%ROWTYPE;
BEGIN
 SELECT*INTO c FROM public.ty_pr_cycle_root WHERE id=NEW.cycle_root_id;SELECT*INTO t FROM public.ty_pr_template WHERE id=NEW.template_id;
 IF c.group_id<>NEW.group_id OR t.group_id<>NEW.group_id OR(TG_OP='INSERT'AND t.status<>'published')OR NEW.config_snapshot IS DISTINCT FROM t.config THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='计划须冻结同集团已发布模板及同一业务周期';END IF;
 IF TG_OP='UPDATE'THEN
  IF NEW.cycle_root_id<>OLD.cycle_root_id OR NEW.group_id<>OLD.group_id OR NEW.version<>OLD.version OR NEW.created_by<>OLD.created_by OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='计划周期根及版本不可改换';END IF;
  IF OLD.status<>'draft'AND(NEW.template_id<>OLD.template_id OR NEW.config_snapshot IS DISTINCT FROM OLD.config_snapshot OR NEW.source_plan_id IS DISTINCT FROM OLD.source_plan_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='运行中模板变更须另建同周期新版';END IF;
  IF OLD.status IN('completed','cancelled')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='完成或取消计划不可重新打开';END IF;
 END IF;
 IF NEW.source_plan_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_pr_plan p WHERE p.id=NEW.source_plan_id AND p.cycle_root_id=NEW.cycle_root_id AND p.id<>NEW.id AND p.version<NEW.version)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同周期复制只创建计划版本，不能换经济根';END IF;
 IF NEW.status='running'AND(NEW.launched_at IS NULL OR NEW.launched_by IS NULL OR NOT EXISTS(SELECT 1 FROM public.ty_pr_target WHERE plan_id=NEW.id AND status='active'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='发起计划须有真实参评关系和发起记录';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_plan_guard BEFORE INSERT OR UPDATE ON ty_pr_plan FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_plan_guard();
CREATE FUNCTION fn_ty_pr_target_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_pr_plan%ROWTYPE;c public.ty_pr_cycle_root%ROWTYPE;e public.ty_employment%ROWTYPE;
BEGIN
 SELECT*INTO p FROM public.ty_pr_plan WHERE id=NEW.plan_id;SELECT*INTO c FROM public.ty_pr_cycle_root WHERE id=p.cycle_root_id;SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
 IF p.group_id<>NEW.group_id OR e.group_id<>NEW.group_id OR e.person_id<>NEW.person_id OR e.company_id<>NEW.company_id OR e.status='cancelled'OR e.hire_date>=c.ends_on OR(e.leave_date IS NOT NULL AND e.leave_date<c.starts_on)OR NOT EXISTS(SELECT 1 FROM public.ty_pr_plan_company WHERE plan_id=p.id AND company_id=NEW.company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='参评对象须为计划范围内同一永久人员及有效实际关系';END IF;
 IF TG_OP='UPDATE'AND(NEW.plan_id<>OLD.plan_id OR NEW.person_id<>OLD.person_id OR NEW.employment_id<>OLD.employment_id OR NEW.company_id<>OLD.company_id OR NEW.evaluation_context<>OLD.evaluation_context OR NEW.personnel_snapshot IS DISTINCT FROM OLD.personnel_snapshot OR NEW.revision<>OLD.revision+1)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='参评身份和冻结人事快照不能改写';END IF;
 IF NEW.status='excluded'AND length(btrim(coalesce(NEW.exclusion_reason,'')))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='排除须有明确依据';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_target_guard BEFORE INSERT OR UPDATE ON ty_pr_target FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_target_guard();
DO $$DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['ty_pr_metric','ty_pr_template','ty_pr_cycle_root','ty_pr_plan','ty_pr_plan_company','ty_pr_target','ty_pr_org_input','ty_pr_rating_assignment','ty_pr_rating_revision','ty_pr_result_root','ty_pr_result_version','ty_pr_publication','ty_pr_acknowledgment','ty_pr_appeal','ty_pr_bonus_month','ty_pr_award_parent','ty_pr_bonus_trial','ty_pr_award_revision','ty_pr_source_alias','ty_pr_notice','ty_pr_import_batch','ty_pr_event']LOOP
 EXECUTE format('CREATE TRIGGER %I BEFORE DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.fn_ty_pr_keep()',tab||'_keep',tab);
 END LOOP;END;$$;
CREATE TRIGGER ty_pr_cycle_keep BEFORE UPDATE ON ty_pr_cycle_root FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_keep();
CREATE TRIGGER ty_pr_event_update_keep BEFORE UPDATE ON ty_pr_event FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_keep();
CREATE TRIGGER ty_pr_alias_keep BEFORE UPDATE ON ty_pr_source_alias FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_keep();
CREATE TRIGGER ty_pr_ack_keep BEFORE UPDATE ON ty_pr_acknowledgment FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_keep();
CREATE TRIGGER ty_pr_trial_keep BEFORE UPDATE ON ty_pr_bonus_trial FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_keep();
CREATE FUNCTION fn_ty_pr_identity(actor bigint,gid bigint)RETURNS text LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE ag bigint;pid bigint;legacy bigint;b_exists boolean;
BEGIN
 SELECT a.person_id,b.account_id IS NOT NULL,CASE WHEN b.account_id IS NOT NULL THEN b.group_id ELSE p.group_id END,CASE WHEN b.account_id IS NOT NULL THEN b.person_id ELSE p.person_id END
 INTO legacy,b_exists,ag,pid FROM public.sys_account a LEFT JOIN public.ty_operator_binding b ON b.account_id=a.id LEFT JOIN public.ty_test_account_profile p ON p.account_id=a.id WHERE a.id=actor AND a.status='active'AND NOT EXISTS(SELECT 1 FROM public.ty_operator_binding z WHERE z.account_id=a.id AND z.status<>'active');
 IF ag IS DISTINCT FROM gid THEN RETURN NULL;END IF;
 IF NOT b_exists AND pid IS NULL AND legacy IS NOT NULL THEN SELECT id INTO pid FROM public.ty_person WHERE group_id=gid AND legacy_person_id=legacy;END IF;
 IF pid IS NOT NULL THEN RETURN'person:'||gid||':'||pid;END IF;RETURN'account:'||actor;
END;$$;
CREATE FUNCTION fn_ty_pr_company_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_pr_plan%ROWTYPE;
BEGIN SELECT*INTO p FROM public.ty_pr_plan WHERE id=NEW.plan_id;IF p.status<>'draft'OR NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.company_id AND group_id=p.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='计划公司范围须在草稿同集团内确定';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pr_company_guard BEFORE INSERT ON ty_pr_plan_company FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_company_guard();
CREATE TRIGGER ty_pr_company_immutable BEFORE UPDATE ON ty_pr_plan_company FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_keep();
CREATE FUNCTION fn_ty_pr_assignment_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE x public.ty_pr_target%ROWTYPE;p public.ty_pr_plan%ROWTYPE;rating public.ty_pr_rating_revision%ROWTYPE;principal text;
BEGIN
 SELECT*INTO x FROM public.ty_pr_target WHERE id=NEW.target_id;SELECT*INTO p FROM public.ty_pr_plan WHERE id=x.plan_id;principal:=public.fn_ty_pr_identity(NEW.rater_account_id,x.group_id);
 IF principal IS NULL OR principal IS DISTINCT FROM NEW.rater_identity_key OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.config_snapshot->'roles')r WHERE r->>'code'=NEW.role_code)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='评分人须为真实有效同集团账号及已配置角色，不得换别名重复计人数';END IF;
 IF NEW.role_code='self'AND NOT public.fn_ty_pr_bound_person(NEW.rater_account_id,x.group_id,x.person_id)OR NEW.role_code<>'self'AND public.fn_ty_pr_actor_is_person(NEW.rater_account_id,x.group_id,x.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='自评须为本人，其他评分角色不得由本人别名冒充';END IF;
 IF NEW.reviewer_account_id IS NOT NULL AND(public.fn_ty_pr_same_actor(NEW.rater_account_id,NEW.reviewer_account_id)OR public.fn_ty_pr_actor_is_person(NEW.reviewer_account_id,x.group_id,x.person_id)OR public.fn_ty_pr_identity(NEW.reviewer_account_id,x.group_id)IS NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='评分上级复核须独立于评分人与受益人';END IF;
 IF EXISTS(SELECT 1 FROM public.ty_pr_rating_assignment a WHERE a.target_id=NEW.target_id AND a.status<>'cancelled'AND a.id<>NEW.id AND public.fn_ty_pr_same_actor(a.rater_account_id,NEW.rater_account_id)AND(a.role_code=NEW.role_code OR NOT coalesce((p.config_snapshot->>'allow_multiple_rating_roles')::boolean,false)))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一自然人不能用多个账号或角色重复占互评人数权重';END IF;
 IF TG_OP='UPDATE'THEN
  IF NEW.target_id<>OLD.target_id OR NEW.rater_account_id<>OLD.rater_account_id OR NEW.rater_identity_key<>OLD.rater_identity_key OR NEW.role_code<>OLD.role_code OR NEW.created_by<>OLD.created_by OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='评分分派身份不可改换，改派须保留旧任务并新建有据分派';END IF;
  IF OLD.status='cancelled'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已取消评分任务不可重新生效';END IF;
 END IF;
 IF NEW.current_rating_id IS NOT NULL THEN SELECT*INTO rating FROM public.ty_pr_rating_revision WHERE id=NEW.current_rating_id;IF rating.assignment_id<>NEW.id OR rating.status IS DISTINCT FROM NEW.status THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='任务当前评分须引用本分派同状态的真实修订';END IF;END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_assignment_guard BEFORE INSERT OR UPDATE ON ty_pr_rating_assignment FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_assignment_guard();
CREATE FUNCTION fn_ty_pr_rating_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE a public.ty_pr_rating_assignment%ROWTYPE;x public.ty_pr_target%ROWTYPE;p public.ty_pr_plan%ROWTYPE;item jsonb;v numeric;
BEGIN
 SELECT*INTO a FROM public.ty_pr_rating_assignment WHERE id=NEW.assignment_id FOR UPDATE;SELECT*INTO x FROM public.ty_pr_target WHERE id=a.target_id;SELECT*INTO p FROM public.ty_pr_plan WHERE id=x.plan_id;
 IF a.status='cancelled'OR p.status NOT IN('running','paused')OR(p.status='paused'AND NEW.status<>'draft')OR NOT public.fn_ty_pr_same_actor(NEW.actor_id,a.rater_account_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='评分须由真实获派本人签名并属于在办计划';END IF;
 IF TG_OP='UPDATE'THEN
  IF NEW.assignment_id<>OLD.assignment_id OR NEW.version<>OLD.version OR NEW.actor_id<>OLD.actor_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='不能改写原评分署名或所属修订';END IF;
  IF OLD.status<>'draft'AND(to_jsonb(NEW)-ARRAY['status','reviewed_by','reviewed_at','review_reason'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','reviewed_by','reviewed_at','review_reason'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已提交评价内容不可由审核人直接改分保留原署名';END IF;
  IF OLD.status IN('reviewed','returned')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已办理评分修订不可重写，须新版本';END IF;
 END IF;
 IF NEW.status IN('submitted','reviewed')THEN
  IF NEW.source_hash IS NULL OR length(NEW.source_hash)<>64 OR NEW.submitted_at IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='正式提交须冻结内容与真实提交时间';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p.config_snapshot->'items')LOOP
   IF(item->>'weight')::numeric=0 THEN CONTINUE;END IF;
   IF NOT(NEW.values? (item->>'code'))OR NEW.values->(item->>'code')->>'score'IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='必要指标缺评不能当作0或自动平均';END IF;
   v:=(NEW.values->(item->>'code')->>'score')::numeric;
   IF v<coalesce((item->>'score_min')::numeric,0)OR v>coalesce((item->>'score_max')::numeric,100)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='指标评分超出冻结量表上下限';END IF;
  END LOOP;
 END IF;
 IF NEW.status IN('reviewed','returned')THEN
  IF NEW.reviewed_by IS NULL OR NEW.reviewed_at IS NULL OR length(btrim(coalesce(NEW.review_reason,'')))<4 OR public.fn_ty_pr_same_actor(NEW.actor_id,NEW.reviewed_by)OR public.fn_ty_pr_actor_is_person(NEW.reviewed_by,x.group_id,x.person_id)OR a.reviewer_account_id IS NOT NULL AND NOT public.fn_ty_pr_same_actor(NEW.reviewed_by,a.reviewer_account_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='评分上级复核须有真实独立责任人和明确意见';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_rating_guard BEFORE INSERT OR UPDATE ON ty_pr_rating_revision FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_rating_guard();
CREATE FUNCTION fn_ty_pr_score_snapshot(tid bigint)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE target public.ty_pr_target%ROWTYPE;plan public.ty_pr_plan%ROWTYPE;cycle public.ty_pr_cycle_root%ROWTYPE;role jsonb;item jsonb;rating record;org public.ty_pr_org_input%ROWTYPE;
 issues jsonb:='[]';roles_json jsonb:='[]';rating_json jsonb;org_json jsonb:='[]';org_result jsonb;band jsonb;m date;
 personal numeric:=0;role_sum numeric;one_score numeric;raw numeric;role_count integer;org_total numeric:=0;org_count integer:=0;org_weight numeric;score numeric;
BEGIN
 SELECT*INTO target FROM public.ty_pr_target WHERE id=tid;IF NOT FOUND THEN RETURN jsonb_build_object('score',NULL,'issues',jsonb_build_array('TARGET_MISSING'));END IF;
 SELECT*INTO plan FROM public.ty_pr_plan WHERE id=target.plan_id;SELECT*INTO cycle FROM public.ty_pr_cycle_root WHERE id=plan.cycle_root_id;
 IF target.status<>'active'OR target.goal_state<>'confirmed'THEN issues:=issues||jsonb_build_array('TARGET_OR_GOAL_PENDING');END IF;
 org_weight:=coalesce((plan.config_snapshot->>'organization_weight')::numeric,0);
 IF org_weight<1 THEN
 FOR role IN SELECT value FROM jsonb_array_elements(plan.config_snapshot->'roles')LOOP
  IF(role->>'weight')::numeric=0 THEN CONTINUE;END IF;role_sum:=0;role_count:=0;rating_json:='[]';
  FOR rating IN SELECT a.id assignment_id,a.rater_identity_key,a.status assignment_status,r.* FROM public.ty_pr_rating_assignment a LEFT JOIN public.ty_pr_rating_revision r ON r.id=a.current_rating_id
   WHERE a.target_id=tid AND a.role_code=role->>'code'AND a.status<>'cancelled'ORDER BY a.id LOOP
   IF rating.id IS NULL OR rating.assignment_status NOT IN('submitted','reviewed')OR coalesce((role->>'review_required')::boolean,true)AND rating.assignment_status<>'reviewed'THEN
    issues:=issues||jsonb_build_array('RATING_PENDING:'||rating.assignment_id);CONTINUE;
   END IF;
   one_score:=0;
   FOR item IN SELECT value FROM jsonb_array_elements(plan.config_snapshot->'items')LOOP
    IF(item->>'weight')::numeric=0 THEN CONTINUE;END IF;
    IF rating.values->(item->>'code')->>'score'IS NULL THEN issues:=issues||jsonb_build_array('ITEM_MISSING:'||rating.assignment_id||':'||(item->>'code'));CONTINUE;END IF;
    raw:=(rating.values->(item->>'code')->>'score')::numeric;
    IF item->>'scoring_mode'='normalize_to_100' THEN raw:=(raw-coalesce((item->>'score_min')::numeric,0))*100/(coalesce((item->>'score_max')::numeric,100)-coalesce((item->>'score_min')::numeric,0));END IF;
    one_score:=one_score+raw*(item->>'weight')::numeric;
   END LOOP;
   role_sum:=role_sum+one_score;role_count:=role_count+1;
   rating_json:=rating_json||jsonb_build_array(jsonb_build_object('assignment_id',rating.assignment_id,'rating_id',rating.id,'version',rating.version,'source_hash',rating.source_hash,'status',rating.status,'actor_id',rating.actor_id,'reviewed_by',rating.reviewed_by,'weighted_score',one_score::text));
  END LOOP;
  IF role_count<coalesce((role->>'minimum_count')::integer,1)THEN issues:=issues||jsonb_build_array('ROLE_COUNT_PENDING:'||(role->>'code'));END IF;
  IF role_count>0 THEN personal:=personal+role_sum/role_count*(role->>'weight')::numeric;END IF;
  roles_json:=roles_json||jsonb_build_array(jsonb_build_object('role',role->>'code','weight',role->>'weight','count',role_count,'mean_score',CASE WHEN role_count>0 THEN(role_sum/role_count)::text END,'ratings',rating_json));
 END LOOP;
 END IF;
 IF org_weight>0 THEN
  IF coalesce((plan.config_snapshot->'organization_rules'->>'score_base')::numeric,0)<=0 THEN issues:=issues||jsonb_build_array('ORGANIZATION_SCALE_PENDING');
  ELSE
   FOR m IN SELECT generate_series(date_trunc('month',cycle.starts_on)::date,date_trunc('month',cycle.ends_on-1)::date,interval'1 month')::date LOOP
    SELECT*INTO org FROM public.ty_pr_org_input WHERE plan_id=plan.id AND company_id=target.company_id AND period=m AND metric_code=coalesce(plan.config_snapshot->>'organization_metric_code','operating');
    IF org.id IS NULL OR org.state<>'verified'THEN issues:=issues||jsonb_build_array('ORGANIZATION_INPUT_PENDING:'||m);CONTINUE;END IF;
    org_result:=public.fn_ty_perf_company_score(org.values,plan.config_snapshot->'organization_rules');
    IF org_result->>'score'IS NULL OR jsonb_array_length(org_result->'issues')>0 THEN issues:=issues||jsonb_build_array('ORGANIZATION_RULE_OR_INPUT_BLOCKED:'||org.id);CONTINUE;END IF;
    org_total:=org_total+(org_result->>'score')::numeric/(plan.config_snapshot->'organization_rules'->>'score_base')::numeric*100;org_count:=org_count+1;
    org_json:=org_json||jsonb_build_array(jsonb_build_object('id',org.id,'revision',org.revision,'company_id',org.company_id,'period',org.period,'source_hash',org.source_hash,'score',org_result->>'score','deductions',(SELECT coalesce(jsonb_agg(jsonb_build_object('code',d->>'code','observed',d->>'observed','deduction',d->>'deduction')),'[]'::jsonb)FROM jsonb_array_elements(org_result->'deductions')d)));
   END LOOP;
  END IF;
  IF org_count=0 THEN issues:=issues||jsonb_build_array('ORGANIZATION_MONTHS_MISSING');END IF;
 END IF;
 IF jsonb_array_length(issues)=0 THEN score:=round(personal*(1-org_weight)+CASE WHEN org_weight>0 THEN org_total/org_count*org_weight ELSE 0 END,6);band:=public.fn_ty_perf_rating(score,plan.config_snapshot->'rating_bands');IF band IS NULL THEN issues:=issues||jsonb_build_array('RATING_BAND_MISSING');END IF;END IF;
 RETURN jsonb_build_object('target_id',target.id,'plan_id',plan.id,'cycle_root_id',cycle.id,'template_id',plan.template_id,'personnel_snapshot',target.personnel_snapshot,'goals',target.goals,
  'score',CASE WHEN jsonb_array_length(issues)=0 THEN score::text END,'grade',band->>'grade','roles',roles_json,'organization_sources',org_json,'organization_weight',org_weight::text,'issues',issues,'rounding','half_up_6','engine','tyhr-pr-score-v1');
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR division_by_zero THEN RETURN jsonb_build_object('score',NULL,'issues',issues||jsonb_build_array('SCORE_VALUE_INVALID'),'engine','tyhr-pr-score-v1');END;$$;

CREATE FUNCTION fn_ty_pr_hash(v jsonb)RETURNS text LANGUAGE sql IMMUTABLE SET search_path=''AS $$SELECT encode(sha256(convert_to(v::text,'UTF8')),'hex');$$;
CREATE FUNCTION fn_ty_pr_input_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE t public.ty_pr_target%ROWTYPE;p public.ty_pr_plan%ROWTYPE;c public.ty_pr_cycle_root%ROWTYPE;gid bigint;beneficiary bigint;
BEGIN
 IF TG_TABLE_NAME='ty_pr_org_input'THEN SELECT*INTO p FROM public.ty_pr_plan WHERE id=NEW.plan_id;gid:=NEW.group_id;
  IF gid<>p.group_id OR NOT EXISTS(SELECT 1 FROM public.ty_pr_plan_company WHERE plan_id=p.id AND company_id=NEW.company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='组织指标必须属于计划已明确的公司';END IF;
 ELSE SELECT*INTO t FROM public.ty_pr_target WHERE id=NEW.target_id;SELECT*INTO p FROM public.ty_pr_plan WHERE id=t.plan_id;gid:=t.group_id;beneficiary:=t.person_id;END IF;
 SELECT*INTO c FROM public.ty_pr_cycle_root WHERE id=p.cycle_root_id;
 IF NEW.period<c.starts_on OR NEW.period>=c.ends_on OR NEW.period<>date_trunc('month',NEW.period)::date OR length(btrim(NEW.evidence_ref))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='月度来源期间必须在考核周期且有明确凭据';END IF;
 IF TG_OP='UPDATE'THEN
  IF NEW.revision<>OLD.revision+1 OR NEW.created_by<>OLD.created_by OR(to_jsonb(NEW)-ARRAY['revision','state','verified_by','verified_at','source_hash','values','attainment','bonus_base','base_unit','eligibility_weight','grade_id','currency','evidence_ref','source_ref'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['revision','state','verified_by','verified_at','source_hash','values','attainment','bonus_base','base_unit','eligibility_weight','grade_id','currency','evidence_ref','source_ref'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='月度来源身份不可改写且须核对当前版本';END IF;
  IF OLD.state='verified'AND(NEW.state<>'draft'OR(to_jsonb(NEW)-ARRAY['revision','state','verified_by','verified_at','source_hash'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['revision','state','verified_by','verified_at','source_hash']))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核月度来源须先有据退回草稿，不能直接覆盖';END IF;
 END IF;
 IF NEW.state='verified'THEN
  IF NEW.verified_by IS NULL OR public.fn_ty_pr_same_actor(NEW.created_by,NEW.verified_by)OR beneficiary IS NOT NULL AND public.fn_ty_pr_actor_is_person(NEW.verified_by,gid,beneficiary)OR public.fn_ty_pr_identity(NEW.verified_by,gid)IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='月度来源必须由真实独立人员核定';END IF;
  IF TG_TABLE_NAME='ty_pr_org_input'THEN IF NEW.source_hash IS DISTINCT FROM public.fn_ty_pr_hash(NEW.values)OR NEW.verified_at IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='组织指标核定须冻结精确值与时间';END IF;
  ELSE IF NEW.attainment IS NULL OR NEW.attainment<0 OR NEW.bonus_base IS NULL OR NEW.eligibility_weight IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='奖金月度达成、基准和资格必须完整核定';END IF;END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_org_guard BEFORE INSERT OR UPDATE ON ty_pr_org_input FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_input_guard();
CREATE TRIGGER ty_pr_bonus_month_guard BEFORE INSERT OR UPDATE ON ty_pr_bonus_month FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_input_guard();

CREATE FUNCTION fn_ty_pr_result_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_pr_result_root%ROWTYPE;t public.ty_pr_target%ROWTYPE;p public.ty_pr_plan%ROWTYPE;s jsonb;band jsonb;w public.ty_workflow_instance%ROWTYPE;
BEGIN
 SELECT*INTO r FROM public.ty_pr_result_root WHERE id=NEW.root_id FOR UPDATE;SELECT*INTO t FROM public.ty_pr_target WHERE id=NEW.target_id;SELECT*INTO p FROM public.ty_pr_plan WHERE id=t.plan_id;
 IF t.group_id<>r.group_id OR t.company_id<>r.company_id OR t.person_id<>r.person_id OR t.employment_id<>r.employment_id OR t.evaluation_context<>r.evaluation_context OR p.cycle_root_id<>r.cycle_root_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩根、永久人、实际关系与考核上下文必须完全相符';END IF;
 IF TG_OP='INSERT'THEN IF NEW.status NOT IN('calculated','proposed')OR NEW.expected_head_revision<>r.head_revision OR NEW.expected_approved_id IS DISTINCT FROM r.current_approved_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩须从当前根头生成待核版本';END IF;
 ELSE
  IF OLD.status IN('approved','rejected','cancelled')OR NEW.revision<>OLD.revision+1 OR(to_jsonb(NEW)-ARRAY['revision','status','approved_by','approved_at','approval_reason','approval_instance_id'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['revision','status','approved_by','approved_at','approval_reason','approval_instance_id'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核成绩不可覆写，审批只能推进同一冻结意图';END IF;
 END IF;
 IF NEW.status IN('proposed','approved')THEN
  s:=public.fn_ty_pr_score_snapshot(NEW.target_id);
  IF NEW.source_snapshot IS DISTINCT FROM s OR NEW.source_hash<>public.fn_ty_pr_hash(s)OR jsonb_array_length(s->'issues')<>0 OR NEW.issues IS DISTINCT FROM s->'issues'OR NEW.original_score IS DISTINCT FROM(s->>'score')::numeric OR NEW.score IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='评分或指标来源已变化/未完整核准，须重新生成成绩意图';END IF;
  band:=public.fn_ty_perf_rating(NEW.score,p.config_snapshot->'rating_bands');IF NEW.grade IS DISTINCT FROM band->>'grade'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩等级须使用冻结模板明确阈值';END IF;
  IF NEW.score IS DISTINCT FROM NEW.original_score AND length(btrim(coalesce(NEW.calibration_reason,'')))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='校准分数必须保留原分和有据校准原因';END IF;
  band:=public.fn_ty_perf_rating(NEW.score,p.config_snapshot->'rating_bands');IF band IS NULL OR NEW.grade IS DISTINCT FROM band->>'grade'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩等级须由冻结量表及最终分数推导';END IF;
 END IF;
 IF NEW.status='approved'THEN
  IF NEW.expected_head_revision<>r.head_revision OR NEW.expected_approved_id IS DISTINCT FROM r.current_approved_id THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='该员工成绩头已更新，请重新计算和复核';END IF;
  IF NEW.approved_by IS NULL OR NEW.approved_at IS NULL OR length(btrim(coalesce(NEW.approval_reason,'')))<4 OR public.fn_ty_pr_same_actor(NEW.created_by,NEW.approved_by)OR public.fn_ty_pr_actor_is_person(NEW.approved_by,r.group_id,r.person_id)OR public.fn_ty_pr_identity(NEW.approved_by,r.group_id)IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩必须逐人独立核准，制单人/同人别名/受益本人均不可自核';END IF;
  IF NEW.approval_instance_id IS NOT NULL THEN SELECT*INTO w FROM public.ty_workflow_instance WHERE id=NEW.approval_instance_id;
   IF w.id IS NULL OR w.subject_type<>'performance_result'OR w.subject_id<>NEW.id OR w.status<>'approved'OR w.last_approver_id<>NEW.approved_by OR w.applicant_id<>NEW.created_by THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩审批回执必须是对应真实完成实例';END IF;
  END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_result_guard BEFORE INSERT OR UPDATE ON ty_pr_result_version FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_result_guard();
CREATE FUNCTION fn_ty_pr_result_root_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE e public.ty_employment%ROWTYPE;r public.ty_pr_result_version%ROWTYPE;pub public.ty_pr_publication%ROWTYPE;
BEGIN
 SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
 IF e.person_id<>NEW.person_id OR e.company_id<>NEW.company_id OR e.group_id<>NEW.group_id OR NOT EXISTS(SELECT 1 FROM public.ty_pr_cycle_root WHERE id=NEW.cycle_root_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩根须反查同集团实际雇佣';END IF;
 IF TG_OP='UPDATE'THEN
  IF(to_jsonb(NEW)-ARRAY['current_approved_id','current_published_id','head_revision'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['current_approved_id','current_published_id','head_revision'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩根身份不可修改';END IF;
  IF NEW.current_approved_id IS DISTINCT FROM OLD.current_approved_id THEN
   SELECT*INTO r FROM public.ty_pr_result_version WHERE id=NEW.current_approved_id;
   IF r.id IS NULL OR r.root_id<>NEW.id OR r.status<>'approved'OR r.expected_head_revision<>OLD.head_revision OR r.expected_approved_id IS DISTINCT FROM OLD.current_approved_id OR NEW.head_revision<>OLD.head_revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩根只能CAS推进至当前逐人核准的新版本';END IF;
  ELSIF NEW.head_revision<>OLD.head_revision THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩根版本只能随有效核准推进';END IF;
 END IF;
 IF NEW.current_published_id IS NOT NULL THEN SELECT*INTO pub FROM public.ty_pr_publication WHERE id=NEW.current_published_id;
  IF pub.root_id<>NEW.id OR pub.state<>'published'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='当前发布头必须属于同一真实成绩根';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_result_root_guard BEFORE INSERT OR UPDATE ON ty_pr_result_root FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_result_root_guard();
CREATE FUNCTION fn_ty_pr_publication_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_pr_result_root%ROWTYPE;v public.ty_pr_result_version%ROWTYPE;
BEGIN
 SELECT*INTO r FROM public.ty_pr_result_root WHERE id=NEW.root_id FOR UPDATE;SELECT*INTO v FROM public.ty_pr_result_version WHERE id=NEW.result_id;
 IF v.root_id<>NEW.root_id OR v.status<>'approved'OR(TG_OP='INSERT'AND r.current_approved_id IS DISTINCT FROM v.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='发布只消费该员工当前已核准成绩，不代替审批';END IF;
 IF TG_OP='UPDATE'THEN IF OLD.state<>'published'OR NEW.state<>'withdrawn'OR(to_jsonb(NEW)-ARRAY['state','withdrawn_by','withdrawn_at','withdraw_reason'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','withdrawn_by','withdrawn_at','withdraw_reason'])OR NEW.withdrawn_by IS NULL OR NEW.withdrawn_at IS NULL OR length(btrim(coalesce(NEW.withdraw_reason,'')))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩发布历史只能有据撤回，不可改分或覆盖';END IF;END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_publication_guard BEFORE INSERT OR UPDATE ON ty_pr_publication FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_publication_guard();
CREATE FUNCTION fn_ty_pr_personal_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_pr_result_root%ROWTYPE;pub public.ty_pr_publication%ROWTYPE;v public.ty_pr_result_version%ROWTYPE;
BEGIN
 SELECT*INTO pub FROM public.ty_pr_publication WHERE id=NEW.publication_id;SELECT*INTO r FROM public.ty_pr_result_root WHERE id=pub.root_id;
 IF r.person_id<>NEW.person_id OR NOT public.fn_ty_pr_bound_person((CASE WHEN TG_TABLE_NAME='ty_pr_acknowledgment'THEN to_jsonb(NEW)->>'actor_id'ELSE to_jsonb(NEW)->>'created_by'END)::bigint,r.group_id,r.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩确认和申诉必须由永久人员本人办理';END IF;
 IF TG_TABLE_NAME='ty_pr_appeal'THEN
  IF TG_OP='INSERT'THEN IF pub.state<>'published'OR NEW.status<>'pending'OR length(btrim(NEW.reason))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='只能对真实已发布成绩提交有据申诉';END IF;
  ELSE
   IF OLD.status<>'pending'OR NEW.status='pending'OR NEW.revision<>OLD.revision+1 OR(to_jsonb(NEW)-ARRAY['status','revision','decided_by','decided_at','decision_reason','corrected_result_id'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','decided_by','decided_at','decision_reason','corrected_result_id'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申诉只能从待办有据结案，不可覆写原诉求';END IF;
   IF NEW.status='withdrawn'THEN IF NOT public.fn_ty_pr_same_actor(NEW.created_by,NEW.decided_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='只有原申诉人可撤回未结申诉';END IF;
   ELSE IF NEW.decided_by IS NULL OR NEW.decided_at IS NULL OR length(btrim(coalesce(NEW.decision_reason,'')))<4 OR public.fn_ty_pr_actor_is_person(NEW.decided_by,r.group_id,r.person_id)OR public.fn_ty_pr_same_actor(NEW.created_by,NEW.decided_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申诉结论须真实独立复核';END IF;END IF;
   IF NEW.status='corrected'THEN SELECT*INTO v FROM public.ty_pr_result_version WHERE id=NEW.corrected_result_id;IF v.root_id<>r.id OR v.status<>'approved'OR v.version<=(SELECT version FROM public.ty_pr_result_version WHERE id=pub.result_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申诉改分须引用同根已独立核准的新成绩版本';END IF;END IF;
  END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_ack_guard BEFORE INSERT ON ty_pr_acknowledgment FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_personal_guard();
CREATE TRIGGER ty_pr_appeal_guard BEFORE INSERT OR UPDATE ON ty_pr_appeal FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_personal_guard();

CREATE FUNCTION fn_ty_pr_round_fraction(n numeric,d numeric,mode text)RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path=''AS $$BEGIN IF n<0 OR d<=0 OR mode NOT IN('floor','half_up_2')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='奖金有理数金额或舍入规则无效';END IF;IF mode='floor'THEN RETURN div(n,d);END IF;RETURN div(n*200+d,d*2)/100;END;$$;
CREATE FUNCTION fn_ty_pr_bonus_snapshot(parent_key bigint,result_key bigint)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE parent public.ty_pr_award_parent%ROWTYPE;r public.ty_pr_result_version%ROWTYPE;rr public.ty_pr_result_root%ROWTYPE;t public.ty_pr_target%ROWTYPE;p public.ty_pr_plan%ROWTYPE;c public.ty_pr_cycle_root%ROWTYPE;
 b public.ty_pr_bonus_month%ROWTYPE;policy jsonb;rows_json jsonb:='[]';issues jsonb:='[]';band jsonb;m date;n integer:=0;total_a numeric:=0;total_score numeric:=0;base numeric;raw_a numeric;raw_b numeric;last_base numeric;last_eligible numeric;mean_score numeric;unit_div integer;last_raw_base numeric;last_unit_div integer;total_a_scaled numeric:=0;
BEGIN
 SELECT*INTO parent FROM public.ty_pr_award_parent WHERE id=parent_key;SELECT*INTO r FROM public.ty_pr_result_version WHERE id=result_key;SELECT*INTO rr FROM public.ty_pr_result_root WHERE id=r.root_id;
 IF parent.id IS NULL OR r.id IS NULL OR rr.cycle_root_id<>parent.cycle_root_id OR rr.employment_id<>parent.employment_id OR rr.person_id<>parent.person_id THEN RETURN jsonb_build_object('issues',jsonb_build_array('AWARD_RESULT_RELATION_MISMATCH'));END IF;
 SELECT*INTO t FROM public.ty_pr_target WHERE id=r.target_id;SELECT*INTO p FROM public.ty_pr_plan WHERE id=t.plan_id;SELECT*INTO c FROM public.ty_pr_cycle_root WHERE id=p.cycle_root_id;policy:=p.config_snapshot->'bonus_policy';
 IF r.status<>'approved'OR rr.current_approved_id IS DISTINCT FROM r.id OR NOT EXISTS(SELECT 1 FROM public.ty_pr_publication pub WHERE pub.id=rr.current_published_id AND pub.result_id=r.id AND pub.state='published')THEN issues:=issues||jsonb_build_array('RESULT_NOT_CURRENT_PUBLISHED');END IF;
 IF EXISTS(SELECT 1 FROM public.ty_pr_appeal a JOIN public.ty_pr_publication pub ON pub.id=a.publication_id WHERE pub.root_id=rr.id AND a.status='pending'AND a.block_bonus)THEN issues:=issues||jsonb_build_array('APPEAL_BLOCKS_AWARD');END IF;
 IF policy IS NULL OR coalesce((policy->>'confirmed')::boolean,false)IS NOT TRUE OR jsonb_typeof(policy->'rating_bands')IS DISTINCT FROM'array'OR policy->>'algorithm_a_aggregation'NOT IN('mean','sum')OR policy->>'algorithm_a_rounding'NOT IN('floor','half_up_2')OR policy->>'algorithm_b_rounding'NOT IN('floor','half_up_2')THEN issues:=issues||jsonb_build_array('BONUS_POLICY_UNCONFIRMED');END IF;
 FOR m IN SELECT d::date FROM generate_series(date_trunc('month',c.starts_on),date_trunc('month',c.ends_on-1),interval'1 month')d LOOP
  SELECT*INTO b FROM public.ty_pr_bonus_month WHERE target_id=t.id AND period=m;
  IF b.id IS NULL OR b.state<>'verified'OR b.attainment IS NULL OR b.bonus_base IS NULL OR b.eligibility_weight IS NULL OR b.currency<>parent.currency THEN issues:=issues||jsonb_build_array('BONUS_MONTH_PENDING:'||m);CONTINUE;END IF;
  unit_div:=CASE b.base_unit WHEN'monthly'THEN 1 WHEN'quarterly'THEN 3 WHEN'annual'THEN 12 END;base:=b.bonus_base/unit_div;
  band:=public.fn_ty_perf_rating(b.attainment,policy->'rating_bands');
  IF band IS NULL OR(band->>'factor')::numeric<0 THEN issues:=issues||jsonb_build_array('BONUS_FACTOR_MISSING:'||m);CONTINUE;END IF;
  raw_a:=b.attainment*(band->>'factor')::numeric*base*b.eligibility_weight;total_a:=total_a+raw_a;total_a_scaled:=total_a_scaled+b.attainment*(band->>'factor')::numeric*b.bonus_base*b.eligibility_weight*(12/unit_div);total_score:=total_score+b.attainment;n:=n+1;last_base:=base;last_raw_base:=b.bonus_base;last_unit_div:=unit_div;last_eligible:=b.eligibility_weight;
  rows_json:=rows_json||jsonb_build_array(jsonb_build_object('id',b.id,'revision',b.revision,'period',b.period,'attainment',b.attainment::text,'bonus_base',b.bonus_base::text,'base_unit',b.base_unit,'monthly_base',base::text,'eligibility_weight',b.eligibility_weight::text,'factor',band->>'factor','grade',band->>'grade','algorithm_a_raw',raw_a::text,'currency',b.currency,'evidence_ref',b.evidence_ref,'source_ref',b.source_ref));
 END LOOP;
 IF n>0 AND jsonb_array_length(issues)=0 THEN
  raw_a:=public.fn_ty_pr_round_fraction(total_a_scaled,12*CASE policy->>'algorithm_a_aggregation'WHEN'mean'THEN n ELSE 1 END,policy->>'algorithm_a_rounding');mean_score:=total_score/n;SELECT value INTO band FROM jsonb_array_elements(policy->'rating_bands')WHERE total_score>=(value->>'min_score')::numeric*n ORDER BY(value->>'min_score')::numeric DESC LIMIT 1;
  IF band IS NULL THEN issues:=issues||jsonb_build_array('MEAN_FACTOR_MISSING');ELSE raw_b:=public.fn_ty_pr_round_fraction(total_score*(band->>'factor')::numeric*last_raw_base*last_eligible,n*last_unit_div,policy->>'algorithm_b_rounding');END IF;
 ELSE raw_a:=NULL;raw_b:=NULL;END IF;
 RETURN jsonb_build_object('parent_id',parent.id,'result_id',r.id,'result_source_hash',r.source_hash,'result_root_head_revision',rr.head_revision,'cycle_root_id',c.id,'employment_id',parent.employment_id,'purpose_code',parent.purpose_code,'item_code',parent.item_code,'currency',parent.currency,'policy',policy,'months',rows_json,'average_attainment',mean_score::text,'algorithm_a_amount',CASE WHEN jsonb_array_length(issues)=0 THEN raw_a::text END,'algorithm_b_amount',CASE WHEN jsonb_array_length(issues)=0 THEN raw_b::text END,'issues',issues,'engine','tyhr-pr-bonus-v1');
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR division_by_zero THEN RETURN jsonb_build_object('issues',issues||jsonb_build_array('BONUS_VALUE_INVALID'),'engine','tyhr-pr-bonus-v1');END;$$;
CREATE FUNCTION fn_ty_pr_award_parent_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE e public.ty_employment%ROWTYPE;a public.ty_pr_award_revision%ROWTYPE;i public.ty_pay_item_catalog%ROWTYPE;
BEGIN
 SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;SELECT*INTO i FROM public.ty_pay_item_catalog WHERE code=NEW.item_code;
 IF e.person_id<>NEW.person_id OR e.company_id<>NEW.company_id OR e.group_id<>NEW.group_id OR NOT EXISTS(SELECT 1 FROM public.ty_pr_cycle_root WHERE id=NEW.cycle_root_id AND group_id=NEW.group_id)OR length(btrim(NEW.purpose_code))<2 OR i.category<>'cash_earnings'OR i.metadata->>'employee_cash_wage_effect'<>'increase_gross'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='奖金父义务须绑定真实雇佣、稳定周期和有据奖励用途/应发项目';END IF;
 IF TG_OP='UPDATE'THEN
  IF(to_jsonb(NEW)-ARRAY['current_approved_id','head_revision'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['current_approved_id','head_revision'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='奖金用途、币种、项目和真实关系不可通过换版更改';END IF;
  SELECT*INTO a FROM public.ty_pr_award_revision WHERE id=NEW.current_approved_id;
  IF NEW.current_approved_id IS NOT DISTINCT FROM OLD.current_approved_id OR a.parent_id<>NEW.id OR a.status<>'approved'OR a.expected_head_revision<>OLD.head_revision OR NEW.head_revision<>OLD.head_revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='奖金父义务只能CAS推进独立核准版本';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_award_parent_guard BEFORE INSERT OR UPDATE ON ty_pr_award_parent FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_award_parent_guard();
CREATE FUNCTION fn_ty_pr_trial_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE s jsonb;
BEGIN s:=public.fn_ty_pr_bonus_snapshot(NEW.parent_id,NEW.result_id);
 IF NEW.source_snapshot IS DISTINCT FROM s OR NEW.details IS DISTINCT FROM s OR NEW.source_hash<>public.fn_ty_pr_hash(s)OR NEW.issues IS DISTINCT FROM s->'issues'OR NEW.algorithm_a_amount IS DISTINCT FROM(s->>'algorithm_a_amount')::numeric OR NEW.algorithm_b_amount IS DISTINCT FROM(s->>'algorithm_b_amount')::numeric THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='双算法试算须由完整已核月度来源独立复算';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pr_trial_guard BEFORE INSERT ON ty_pr_bonus_trial FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_trial_guard();
CREATE FUNCTION fn_ty_pr_award_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_pr_award_parent%ROWTYPE;trial public.ty_pr_bonus_trial%ROWTYPE;s jsonb;prior numeric;posted_prior numeric;
BEGIN
 SELECT*INTO p FROM public.ty_pr_award_parent WHERE id=NEW.parent_id FOR UPDATE;SELECT*INTO trial FROM public.ty_pr_bonus_trial WHERE id=NEW.trial_id;
 IF trial.parent_id<>p.id OR trial.result_id<>NEW.result_id OR NEW.source_hash<>trial.source_hash OR NEW.target_amount IS DISTINCT FROM(CASE NEW.algorithm WHEN'A'THEN trial.algorithm_a_amount ELSE trial.algorithm_b_amount END)OR jsonb_array_length(trial.issues)>0 OR length(btrim(NEW.reason))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='正式奖金必须明确选择同一父义务的A/B无阻断试算之一';END IF;
 IF TG_OP='INSERT'THEN IF NEW.status<>'proposed'OR NEW.expected_head_revision<>p.head_revision THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='奖金意图须从当前义务头提出';END IF;
 ELSE IF OLD.status<>'proposed'OR NEW.status NOT IN('approved','rejected','cancelled')OR NEW.revision<>OLD.revision+1 OR(to_jsonb(NEW)-ARRAY['status','revision','approved_by','approved_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','approved_by','approved_at'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='奖金意图冻结后只能核准/驳回/撤回，更正须新版本';END IF;END IF;
 IF NEW.status='approved'THEN
  s:=public.fn_ty_pr_bonus_snapshot(p.id,NEW.result_id);
  IF s IS DISTINCT FROM trial.source_snapshot OR NEW.expected_head_revision<>p.head_revision THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='成绩、月度基准、申诉或奖金根已变化，请重新试算';END IF;
  IF NEW.approved_by IS NULL OR NEW.approved_at IS NULL OR public.fn_ty_pr_same_actor(NEW.created_by,NEW.approved_by)OR public.fn_ty_pr_actor_is_person(NEW.approved_by,p.group_id,p.person_id)OR public.fn_ty_pr_identity(NEW.approved_by,p.group_id)IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='正式奖金必须由非制单人、非同人别名、非受益人逐人核准';END IF;
  SELECT target_amount INTO prior FROM public.ty_pr_award_revision WHERE id=p.current_approved_id;SELECT coalesce(sum(a.delta),0)INTO posted_prior FROM public.ty_pay_adoption a JOIN public.ty_pay_obligation o ON o.id=a.obligation_id WHERE a.state='confirmed'AND o.group_id=p.group_id AND o.person_id=p.person_id AND o.employment_id=p.employment_id AND o.purpose='employee_cash'AND o.economic_key IN(SELECT canonical_economic_key FROM public.ty_pr_source_alias WHERE parent_id=p.id);
  IF NEW.target_amount<greatest(coalesce(prior,0),coalesce(posted_prior,0))AND length(btrim(coalesce(NEW.recovery_basis_ref,'')))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='累计目标下降须独立核准更正依据，不可冒作自动追扣';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_award_guard BEFORE INSERT OR UPDATE ON ty_pr_award_revision FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_award_guard();
CREATE FUNCTION fn_ty_pr_alias_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_pr_award_parent%ROWTYPE;c public.ty_perf_cycle%ROWTYPE;r public.ty_pr_cycle_root%ROWTYPE;rc public.ty_pay_config%ROWTYPE;key text;history_key text;history_count integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.ty_pr_event e WHERE e.id=NEW.proposal_event_id AND e.entity_type='source_alias_request'AND e.action='source.alias.proposed'AND e.actor_id=NEW.created_by AND e.entity_id=NEW.parent_id AND(e.after_data->>'legacy_cycle_id')::bigint=NEW.legacy_cycle_id AND e.after_data->>'canonical_economic_key'=NEW.canonical_economic_key)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='桥接须引用另一真实操作人冻结提出的事实，不能捏造制单人';END IF;
 SELECT*INTO p FROM public.ty_pr_award_parent WHERE id=NEW.parent_id;IF EXISTS(SELECT 1 FROM public.ty_pr_source_alias x JOIN public.ty_pr_award_parent y ON y.id=x.parent_id WHERE y.group_id=p.group_id AND x.canonical_economic_key=NEW.canonical_economic_key AND x.parent_id<>p.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一旧经济根不可桥接两个原生奖励父义务';END IF;IF EXISTS(SELECT 1 FROM public.ty_pay_adoption a JOIN public.ty_pr_award_revision v ON v.id=(CASE WHEN a.source_domain='performance_award'THEN a.source_id::bigint END)JOIN public.ty_pay_obligation o ON o.id=a.obligation_id WHERE a.source_domain='performance_award'AND v.parent_id=p.id AND o.economic_key<>NEW.canonical_economic_key)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原生奖金已有另一经济根采用，不能事后静默桥接重复义务；先独立对账更正';END IF;SELECT*INTO c FROM public.ty_perf_cycle WHERE id=NEW.legacy_cycle_id;SELECT*INTO r FROM public.ty_pr_cycle_root WHERE id=p.cycle_root_id;
 IF c.status<>'confirmed'OR NOT EXISTS(SELECT 1 FROM public.ty_perf_result hist_pr WHERE hist_pr.cycle_id=c.id AND hist_pr.result_version=c.result_version AND hist_pr.kind='person_bonus'AND hist_pr.employment_id=p.employment_id AND hist_pr.person_id=p.person_id AND hist_pr.company_id=p.company_id)OR c.group_id<>p.group_id OR c.start_date<>r.starts_on OR c.end_date<>r.ends_on OR c.currency_code<>p.currency OR NEW.legacy_employment_id<>p.employment_id OR public.fn_ty_pr_same_actor(NEW.created_by,NEW.approved_by)OR public.fn_ty_pr_actor_is_person(NEW.approved_by,p.group_id,p.person_id)OR length(btrim(NEW.reason))<4 OR length(btrim(NEW.evidence_ref))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='旧新绩效桥接须明确同经济周期/雇佣/币种且独立审核，不可按姓名金额猜测';END IF;
 SELECT*INTO rc FROM public.ty_pay_config WHERE kind='relationship'AND status='approved'AND group_id=p.group_id AND employment_id=p.employment_id AND valid_from<=c.payout_period AND(valid_to IS NULL OR c.payout_period<valid_to)ORDER BY revision DESC,id DESC LIMIT 1;
 key:='performance:'||(rc.data->>'actual_relationship_key')||':'||to_char(c.start_date,'YYYY-MM-DD')||':'||to_char(c.end_date,'YYYY-MM-DD')||':'||to_char(c.payout_period,'YYYY-MM-DD');
 SELECT count(DISTINCT o.economic_key),min(o.economic_key)INTO history_count,history_key FROM public.ty_pay_adoption a JOIN public.ty_perf_result legacy_pr ON legacy_pr.id=(CASE WHEN a.source_domain='performance_result'THEN a.source_id::bigint END)JOIN public.ty_pay_obligation o ON o.id=a.obligation_id WHERE legacy_pr.cycle_id=NEW.legacy_cycle_id AND legacy_pr.employment_id=NEW.legacy_employment_id AND o.group_id=p.group_id AND o.company_id=p.company_id AND o.person_id=p.person_id AND o.employment_id=p.employment_id AND o.currency=p.currency AND o.purpose='employee_cash';
 IF history_count>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='该旧来源已有多个经济根采用，须先人工独立对账，不能静默合并';END IF;
 IF history_count=1 THEN key:=history_key;END IF;
 IF key IS NULL OR NEW.canonical_economic_key<>key THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='桥接经济根必须来自已核真实关系及旧奖金权威期间';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_pr_alias_guard BEFORE INSERT ON ty_pr_source_alias FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_alias_guard();

CREATE FUNCTION fn_ty_pr_import_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
BEGIN
 IF TG_OP='UPDATE'THEN IF OLD.status<>'validated'OR NEW.status<>'applied'OR NEW.revision<>OLD.revision+1 OR(to_jsonb(NEW)-ARRAY['revision','status'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['revision','status'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='导入只能原子采用已预检冻结行，不可覆盖原文件/预检问题';END IF;END IF;
 IF NEW.plan_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_pr_plan WHERE id=NEW.plan_id AND group_id=NEW.group_id)OR jsonb_typeof(NEW.parsed_rows)IS DISTINCT FROM'array'OR jsonb_typeof(NEW.issues)IS DISTINCT FROM'array'OR length(NEW.source_hash)<>64 OR NEW.status IN('validated','applied')AND jsonb_array_length(NEW.issues)>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='导入所属范围/文件哈希/阻断问题不一致';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pr_import_guard BEFORE INSERT OR UPDATE ON ty_pr_import_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_import_guard();
CREATE FUNCTION fn_ty_pr_notice_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
BEGIN
 IF TG_OP='UPDATE'AND(to_jsonb(NEW)-'read_at')IS DISTINCT FROM(to_jsonb(OLD)-'read_at')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='成绩通知只能记录已阅，投递和业务结果不可互改';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sys_account a LEFT JOIN public.ty_operator_binding b ON b.account_id=a.id LEFT JOIN public.ty_test_account_profile p ON p.account_id=a.id WHERE a.id=NEW.recipient_account_id AND CASE WHEN b.account_id IS NOT NULL THEN b.group_id ELSE p.group_id END=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='绩效通知收件人必须属于同一集团';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_pr_notice_guard BEFORE INSERT OR UPDATE ON ty_pr_notice FOR EACH ROW EXECUTE FUNCTION fn_ty_pr_notice_guard();
CREATE FUNCTION fn_ty_pr_legacy_replaced(cycle_key bigint,employment_key bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT EXISTS(SELECT 1 FROM public.ty_pr_source_alias s JOIN public.ty_pr_award_parent p ON p.id=s.parent_id JOIN public.ty_pr_award_revision a ON a.id=p.current_approved_id WHERE s.legacy_cycle_id=cycle_key AND s.legacy_employment_id=employment_key AND a.status='approved');$$;
CREATE FUNCTION fn_ty_pr_pay_key(batch_key bigint,adoption_key bigint)RETURNS text LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE a public.ty_pay_adoption%ROWTYPE;v public.ty_pr_award_revision%ROWTYPE;p public.ty_pr_award_parent%ROWTYPE;b public.ty_pay_batch%ROWTYPE;o public.ty_pay_obligation%ROWTYPE;i public.ty_pay_item%ROWTYPE;k text;
BEGIN
 SELECT*INTO a FROM public.ty_pay_adoption WHERE id=adoption_key AND batch_id=batch_key;SELECT*INTO b FROM public.ty_pay_batch WHERE id=batch_key;SELECT*INTO v FROM public.ty_pr_award_revision WHERE id=a.source_id::bigint;SELECT*INTO p FROM public.ty_pr_award_parent WHERE id=v.parent_id;SELECT*INTO o FROM public.ty_pay_obligation WHERE id=a.obligation_id;SELECT*INTO i FROM public.ty_pay_item WHERE adoption_id=a.id;
 IF a.source_domain<>'performance_award'OR p.id IS NULL OR p.group_id<>b.group_id OR p.company_id<>b.company_id OR p.person_id IS DISTINCT FROM o.person_id OR p.employment_id IS DISTINCT FROM o.employment_id OR p.item_code IS DISTINCT FROM i.code OR p.currency<>b.currency THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='绩效采用须反查同一权威奖金父义务及实际雇佣/项目/币种';END IF;
 SELECT min(canonical_economic_key)INTO k FROM public.ty_pr_source_alias WHERE parent_id=p.id;
 IF EXISTS(SELECT 1 FROM public.ty_pr_source_alias WHERE parent_id=p.id AND canonical_economic_key IS DISTINCT FROM k)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='多个旧来源经济根不一致，须先人工核对防重';END IF;
 RETURN coalesce(k,'performance_award:'||p.id);
END;$$;
CREATE FUNCTION fn_ty_pr_pay_expected(batch_key bigint,adoption_key bigint)RETURNS numeric LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE a public.ty_pay_adoption%ROWTYPE;v public.ty_pr_award_revision%ROWTYPE;p public.ty_pr_award_parent%ROWTYPE;b public.ty_pay_batch%ROWTYPE;r public.ty_pr_result_version%ROWTYPE;rr public.ty_pr_result_root%ROWTYPE;pub public.ty_pr_publication%ROWTYPE;tags jsonb;book public.ty_pay_config%ROWTYPE;
BEGIN
 PERFORM public.fn_ty_pr_pay_key(batch_key,adoption_key);SELECT*INTO a FROM public.ty_pay_adoption WHERE id=adoption_key;SELECT*INTO b FROM public.ty_pay_batch WHERE id=batch_key;SELECT*INTO v FROM public.ty_pr_award_revision WHERE id=a.source_id::bigint;SELECT*INTO p FROM public.ty_pr_award_parent WHERE id=v.parent_id;SELECT*INTO r FROM public.ty_pr_result_version WHERE id=v.result_id;SELECT*INTO rr FROM public.ty_pr_result_root WHERE id=r.root_id;SELECT*INTO pub FROM public.ty_pr_publication WHERE id=rr.current_published_id;
 IF v.status<>'approved'OR p.current_approved_id IS DISTINCT FROM v.id OR a.source_revision<>(v.version||':'||p.head_revision) OR v.payout_period<>b.period OR rr.current_approved_id IS DISTINCT FROM r.id OR pub.id IS NULL OR pub.result_id<>r.id OR pub.state<>'published'OR EXISTS(SELECT 1 FROM public.ty_pr_appeal x JOIN public.ty_pr_publication y ON y.id=x.publication_id WHERE y.root_id=rr.id AND x.status='pending'AND x.block_bonus)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='奖金不是当前已核且成绩已发布版本，或有阻断采用的未结申诉';END IF;
 SELECT*INTO book FROM public.ty_pay_config WHERE id=b.rulebook_id;tags:=book.data->'source_treatments'->'performance_award'->p.item_code;IF tags?'wage_tags'THEN tags:=tags->'wage_tags';END IF;
 IF tags IS NULL OR NOT(tags?'hk_adw'AND tags?'cn_average'AND tags?'cn_annual_leave'AND tags?'ordinary_wage')OR EXISTS(SELECT 1 FROM jsonb_each_text(tags)x WHERE x.value NOT IN('include','exclude','not_applicable'))OR NOT EXISTS(SELECT 1 FROM public.ty_pay_item i WHERE i.adoption_id=a.id AND i.wage_tags@>tags)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='绩效入薪须沿已核规则映射ADW/内地平均工资/年假/通常工资范围，不可用算法名称猜测';END IF;
 RETURN v.target_amount;
END;$$;
ALTER FUNCTION fn_ty_pay_extension_expected(bigint,bigint)RENAME TO fn_ty_pay_extension_expected_pre220;
ALTER FUNCTION fn_ty_pay_extension_key(bigint,bigint)RENAME TO fn_ty_pay_extension_key_pre220;
CREATE FUNCTION fn_ty_pay_extension_expected(batch_key bigint,adoption_key bigint)RETURNS numeric LANGUAGE plpgsql SET search_path=''AS $$BEGIN IF EXISTS(SELECT 1 FROM public.ty_pay_adoption WHERE id=adoption_key AND source_domain='performance_award')THEN RETURN public.fn_ty_pr_pay_expected(batch_key,adoption_key);END IF;RETURN public.fn_ty_pay_extension_expected_pre220(batch_key,adoption_key);END;$$;
CREATE FUNCTION fn_ty_pay_extension_key(batch_key bigint,adoption_key bigint)RETURNS text LANGUAGE plpgsql SET search_path=''AS $$BEGIN IF EXISTS(SELECT 1 FROM public.ty_pay_adoption WHERE id=adoption_key AND source_domain='performance_award')THEN RETURN public.fn_ty_pr_pay_key(batch_key,adoption_key);END IF;RETURN public.fn_ty_pay_extension_key_pre220(batch_key,adoption_key);END;$$;

-- Preserve all217 provenance/math guards; add only the220 dispatch and explicit legacy replacement check.
CREATE OR REPLACE FUNCTION fn_ty_pay_authority_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE a public.ty_pay_adoption%ROWTYPE;i public.ty_pay_item%ROWTYPE;r public.ty_pay_row%ROWTYPE;p public.ty_pay_config%ROWTYPE;
 book public.ty_pay_config%ROWTYPE;v jsonb;ctx jsonb;entry record;rule jsonb;result jsonb;expected numeric;metric text;number_value numeric;unknowns integer;rid bigint;state text;source_revision integer;source_currency text;sc public.ty_ps_candidate%ROWTYPE;charge public.ty_dorm_charge%ROWTYPE;other_net numeric;
BEGIN
 IF NEW.status<>'confirmed'OR OLD.status='confirmed'THEN RETURN NEW;END IF;
 SELECT * INTO book FROM public.ty_pay_config WHERE id=NEW.rulebook_id;
 FOR a IN SELECT * FROM public.ty_pay_adoption WHERE batch_id=NEW.id LOOP
  SELECT * INTO i FROM public.ty_pay_item WHERE adoption_id=a.id;SELECT * INTO r FROM public.ty_pay_row WHERE id=i.row_id;expected:=NULL;
  IF a.source_domain='payroll_calculation'THEN
   SELECT * INTO p FROM public.ty_pay_config WHERE id=(a.source_snapshot->>'profile_id')::bigint;
   IF p.status<>'approved'OR p.kind<>'profile'OR p.employment_id<>r.employment_id OR p.system<>NEW.system OR p.currency<>NEW.currency OR p.valid_from>NEW.period OR(p.valid_to IS NOT NULL AND p.valid_to<NEW.period+interval '1 month')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资参数没有当前可用的已核真实来源';END IF;
   ctx:='{}'::jsonb;
   FOR entry IN SELECT * FROM jsonb_each(book.data->'inputs')LOOP
    IF entry.value->>'source'='profile'THEN
     v:=p.data->'parameters'->coalesce(entry.value->>'key',entry.key);
     IF v IS NULL OR v->>'unit' IS DISTINCT FROM entry.value->>'unit'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原生工资参数单位不符或缺失';END IF;
     ctx:=ctx||jsonb_build_object(entry.key,v->'value');
    ELSIF entry.value->>'source'='time_report'THEN
     rid:=(a.source_snapshot->>'report_id')::bigint;metric:=coalesce(entry.value->>'metric',entry.key);
     IF metric NOT IN('planned_minutes','actual_minutes','worked_minutes','overtime_minutes','paid_leave_minutes','unpaid_leave_minutes','late_minutes','early_minutes','missing_punches','worked_hours','overtime_hours')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='数据库尚未支持此核勤派生类型，不得只信任调用端金额';END IF;
     EXECUTE 'SELECT v.status FROM public.ty_time_report_version v JOIN public.ty_time_report_root h ON h.current_report_id=v.id WHERE v.id=$1 AND v.group_id=$2 AND v.period=$3 AND(v.company_id IS NULL OR v.company_id=$4)AND h.employment_id=$5 AND h.owner_company_id=$4 AND h.perspective=''employer'''INTO state USING rid,NEW.group_id,NEW.period,NEW.company_id,r.employment_id;
     IF state IS DISTINCT FROM 'confirmed'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资只能引用本主体期间已确认核勤';END IF;
     EXECUTE format('SELECT sum(%I),count(*)FILTER(WHERE %I IS NULL)FROM public.ty_time_report_line WHERE report_id=$1 AND employment_id=$2 AND home_company_id=$3 AND NOT receiving_store_only',replace(metric,'_hours','_minutes'),replace(metric,'_hours','_minutes'))INTO number_value,unknowns USING rid,r.employment_id,NEW.company_id;
     IF number_value IS NULL OR unknowns>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='核勤输入待核不能充作零';END IF;
     ctx:=ctx||jsonb_build_object(entry.key,CASE WHEN metric LIKE '%_hours'THEN public.fn_ty_payroll_fraction(number_value,60)ELSE to_jsonb(number_value::text)END);
    ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资输入来源适配尚未安装';END IF;
   END LOOP;
   FOR rule IN SELECT * FROM jsonb_array_elements(book.data->'compiled'->'order')LOOP
    result:=public.fn_ty_payroll_eval(rule->'formula',ctx);ctx:=ctx||jsonb_build_object(rule->>'code',result->'v');
    IF rule->>'code'=i.code THEN expected:=public.fn_ty_payroll_money(result->'v');IF i.wage_tags IS DISTINCT FROM rule->'wage_tags'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资项目法定工资范围标签不符合已批准规则';END IF;END IF;
   END LOOP;
  ELSIF a.source_domain='leave_cash'THEN
   SELECT round(greatest(gross_numerator::numeric/gross_denominator::numeric-normal_covered,0),2),revision,currency INTO expected,source_revision,source_currency FROM public.ty_leave_lifecycle_cash_obligation WHERE id=a.source_id::bigint AND status='confirmed_source';
   IF source_revision::text IS DISTINCT FROM a.source_revision OR source_currency IS DISTINCT FROM NEW.currency THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='假期现金义务版本或币种已变';END IF;
  ELSIF a.source_domain='performance_result'THEN
   IF EXISTS(SELECT 1 FROM public.ty_perf_result hist_pr WHERE hist_pr.id=a.source_id::bigint AND public.fn_ty_pr_legacy_replaced(hist_pr.cycle_id,hist_pr.employment_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='旧绩效来源已显式桥接并由原生核准版接管，不能回抬旧金额';END IF;
   SELECT round(x.amount,2)INTO expected FROM public.ty_perf_result x JOIN public.ty_perf_cycle c ON c.id=x.cycle_id WHERE x.id=a.source_id::bigint AND c.status='confirmed'AND x.result_version=c.result_version AND x.result_version::text=a.source_revision AND x.kind='person_bonus'AND x.company_id=NEW.company_id AND x.person_id=r.person_id AND x.employment_id=r.employment_id AND x.period=NEW.period AND c.currency_code=NEW.currency AND jsonb_array_length(x.issues)=0;
  ELSIF a.source_domain='people_candidate'THEN
   SELECT * INTO sc FROM public.ty_ps_candidate WHERE id=a.source_id::bigint;
   IF sc.group_id<>NEW.group_id OR sc.company_id<>NEW.company_id OR sc.currency<>NEW.currency OR sc.revision::text<>split_part(a.source_revision,':',1) OR EXISTS(SELECT 1 FROM public.ty_ps_candidate x WHERE x.group_id=sc.group_id AND x.module=sc.module AND x.parent_key=sc.parent_key AND x.kind=sc.kind AND x.revision>sc.revision)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='配套候选已被替代或主体币种不符';END IF;
   expected:=sc.target;
   IF sc.kind='company_cost'AND sc.module='dormitory'THEN
    SELECT b.amount-coalesce(sum(c.target),0)INTO expected FROM public.ty_dorm_bill b LEFT JOIN public.ty_dorm_charge c ON c.bill_id=b.id WHERE b.id=(a.source_snapshot->'document'->>'id')::bigint AND b.state='posted'GROUP BY b.id;
   END IF;
   IF sc.kind='employee_charge'THEN
    SELECT * INTO charge FROM public.ty_dorm_charge WHERE id=(a.source_snapshot->>'charge_id')::bigint;
    IF charge.id IS NULL OR NOT charge.payroll_allowed OR charge.disputed OR charge.wage_guard_ref IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='扣结授权或争议状态待核';END IF;
    IF EXISTS(SELECT 1 FROM public.ty_dorm_settlement ds WHERE ds.charge_id=charge.id AND ds.source_key NOT LIKE 'PAY217:%' AND(ds.state IN('unknown','reserved')OR ds.method='payroll'AND ds.state='confirmed'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='其他渠道结算未知，不能重复收取';END IF;
    SELECT coalesce(sum(CASE WHEN method='refund'THEN -amount ELSE amount END),0)INTO other_net FROM public.ty_dorm_settlement ds WHERE ds.charge_id=charge.id AND ds.source_key NOT LIKE 'PAY217:%' AND ds.state='confirmed';
    expected:=least(greatest(charge.target-other_net,0),charge.payroll_limit);
   END IF;
  ELSIF a.source_domain IN('statutory_calculation','performance_award')THEN expected:=public.fn_ty_pay_extension_expected(NEW.id,a.id);
  ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='未经权威来源适配的金额不能确认';END IF;
  IF expected IS NULL OR a.target<>expected THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资采用目标不符合数据库权威来源/已批准公式独立复算';END IF;
 END LOOP;RETURN NEW;
END;$$;

-- Preserve all217 provenance/math guards; add only the220 dispatch and explicit legacy replacement check.
CREATE OR REPLACE FUNCTION fn_ty_pay_reverse_provenance()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE x record;s record;k text;item_code text;rc public.ty_pay_config%ROWTYPE;
BEGIN
 IF NEW.status<>'confirmed'OR OLD.status='confirmed'THEN RETURN NEW;END IF;
 FOR x IN SELECT a.*,i.code,i.cash_wage_effect,i.cost_atom,r.person_id,r.employment_id,r.relationship_config_id,o.economic_key FROM public.ty_pay_adoption a JOIN public.ty_pay_item i ON i.adoption_id=a.id JOIN public.ty_pay_row r ON r.id=i.row_id JOIN public.ty_pay_obligation o ON o.id=a.obligation_id WHERE a.batch_id=NEW.id LOOP
  SELECT * INTO rc FROM public.ty_pay_config WHERE id=x.relationship_config_id;
  IF x.employment_id IS NOT NULL AND(rc.id IS NULL OR rc.kind<>'relationship'OR rc.status<>'approved'OR rc.person_id<>x.person_id OR rc.employment_id<>x.employment_id OR rc.group_id<>NEW.group_id OR rc.company_id<>NEW.company_id OR rc.system<>NEW.system OR rc.data->>'pay_subject_key'IS DISTINCT FROM NEW.pay_subject_key OR rc.data->>'tax_subject_key'IS DISTINCT FROM NEW.tax_subject_key OR rc.data->>'contribution_subject_key'IS DISTINCT FROM NEW.contribution_subject_key)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资实际关系与发薪/税务/供款主体必须反向一致';END IF;
  IF x.source_domain='payroll_calculation'THEN
   SELECT * INTO s FROM public.ty_pay_config WHERE id=(x.source_snapshot->>'profile_id')::bigint;
   IF s.group_id<>NEW.group_id OR s.company_id<>NEW.company_id OR s.person_id<>x.person_id OR s.employment_id<>x.employment_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资档案来源不能借用其他主体或人员';END IF;
   SELECT 'payroll:'||(rc.data->>'actual_relationship_key')||':'||to_char(NEW.period,'YYYY-MM-DD')||':'||coalesce(metadata->>'exclusion_group',code)INTO k FROM public.ty_pay_item_catalog WHERE code=x.code;
  ELSIF x.source_domain='leave_cash'THEN
   SELECT o.*,r.id rel_id,r.group_id,r.person_id INTO s FROM public.ty_leave_lifecycle_cash_obligation o JOIN public.ty_leave_account a ON a.id=o.account_id JOIN public.ty_leave_relationship r ON r.id=a.relationship_id WHERE o.id=x.source_id::bigint;
   IF s.group_id<>NEW.group_id OR s.person_id<>x.person_id OR NOT EXISTS(SELECT 1 FROM public.ty_leave_relationship_employment WHERE relationship_id=s.rel_id AND employment_id=x.employment_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='假期现金来源须属于同集团同人真实关系';END IF;k:='leave:'||s.rel_id||':'||s.root_key;
  ELSIF x.source_domain='people_candidate'THEN
   SELECT * INTO s FROM public.ty_ps_candidate WHERE id=x.source_id::bigint;
   IF s.group_id<>NEW.group_id OR s.company_id<>NEW.company_id OR s.person_id IS DISTINCT FROM x.person_id OR s.employment_id IS DISTINCT FROM x.employment_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='配套来源不可搬人搬主体';END IF;
   k:='people:'||s.module||':'||s.parent_key||':'||s.kind;
   IF s.kind='employee_charge'THEN
    IF s.source_ref IS DISTINCT FROM 'dorm_charge:'||(x.source_snapshot->>'charge_id')OR NOT EXISTS(SELECT 1 FROM public.ty_dorm_charge c WHERE c.id=(x.source_snapshot->>'charge_id')::bigint AND c.person_id=x.person_id AND c.employment_id=x.employment_id AND c.group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='费用采用须反查同一真实个人费用';END IF;
   ELSIF s.kind='noncash_benefit'THEN k:='people:noncash:'||s.employment_id||':'||to_char(NEW.period,'YYYY-MM-DD')||':'||x.code;
   ELSIF s.kind='company_cost'AND s.cost_basis='allocation'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已含成本分摊只能保留引用，不得伪造新增应付或成本';END IF;
  ELSIF x.source_domain='performance_result'THEN
   IF EXISTS(SELECT 1 FROM public.ty_perf_result hist_pr WHERE hist_pr.id=x.source_id::bigint AND public.fn_ty_pr_legacy_replaced(hist_pr.cycle_id,hist_pr.employment_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='旧绩效来源已显式桥接并由原生核准版接管';END IF;
   SELECT r.*,c.group_id,c.start_date,c.end_date INTO s FROM public.ty_perf_result r JOIN public.ty_perf_cycle c ON c.id=r.cycle_id WHERE r.id=x.source_id::bigint;
   IF s.group_id<>NEW.group_id OR s.person_id<>x.person_id OR s.employment_id<>x.employment_id OR s.company_id<>NEW.company_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='绩效采用必须反查同一永久人员及真实雇佣';END IF;
   k:='performance:'||(rc.data->>'actual_relationship_key')||':'||to_char(s.start_date,'YYYY-MM-DD')||':'||to_char(s.end_date,'YYYY-MM-DD')||':'||to_char(s.period,'YYYY-MM-DD');
  ELSIF x.source_domain IN('statutory_calculation','performance_award')THEN k:=public.fn_ty_pay_extension_key(NEW.id,x.id);
  ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='来源反向适配尚未实现';END IF;
  IF k IS NULL OR x.economic_key IS DISTINCT FROM k THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资经济根必须由权威来源反查，不能用规则或路径别名新造义务';END IF;
 END LOOP;RETURN NEW;END;$$;
